// ---- The brand mark's shape, from the frame ------------------------
//
// An open A in half-block cells: the frame draws each cell as a
// `linear-gradient(top 50%, bottom 50%)`, which in a terminal is `▀` with
// an independent foreground and background. Redrawn from the frame's
// 6 rows to a terminal's cell shape; baseline.json records why.

pub(crate) const MARK_COLS: usize = 18;
pub(crate) const MARK_ROWS: usize = 7;
/// The glyph every mark cell is drawn with: upper half foreground, lower half background.
pub(crate) const MARK_CELL: char = '▀';

// ---- The grid, from tokens/layout.css -------------------------------
//
// Cell counts. `--body-x` is the one derived value the design states
// outright ("prose: margin + mark column"), and it is emitted as the
// design states it rather than re-derived here, so a disagreement between
// the two would surface as a stage-3 diff rather than hide in a sum.

pub(crate) const MARGIN_X: usize = 3;
pub(crate) const BODY_X: usize = 5;
pub(crate) const MARK_COL: usize = 2;
pub(crate) const GROUP_GAP: usize = 5;
pub(crate) const FACT_COL: usize = 10;
pub(crate) const DETAIL_COL: usize = 9;
pub(crate) const COMMAND_COL: usize = 12;
pub(crate) const NUMBER_COL: usize = 3;
pub(crate) const TREE_W: usize = 28;
pub(crate) const PANE_GAP: usize = 4;
pub(crate) const GUTTER_LN: usize = 5;
pub(crate) const SIGN_COL: usize = 2;
/// The context bar's segments — ten `━` in every frame.
pub(crate) const GAUGE_SEGMENTS: usize = 10;
/// How many of them a percentage fills: `ContextBar.jsx`'s `round(percent / 10)`, clamped.
pub(crate) fn gauge_filled(percent: u8) -> usize {
    ((f64::from(percent) / 10.0).round() as usize).min(GAUGE_SEGMENTS)
}

